"""Original MIT test-only Z80 fixtures for Issues #41/#47; no external ROM/code inputs.
Run python3 tests/fixtures/philips.py to regenerate the sparse hex images.
The system probes slot 1, MSX2 sub-ROM/RAM, then slot 2's AB init vector.
"""
from pathlib import Path

class Z80:
    def __init__(self, base):
        self.base, self.code, self.labels, self.fixups = base, [], {}, []
    def emit(self, *data):
        self.code.extend(data)
    def label(self, name):
        self.labels[name] = self.base + len(self.code)
    def jump(self, opcode, label):
        self.emit(opcode, 0, 0)
        self.fixups.append((len(self.code)-2, label))
    def done(self):
        for offset, label in self.fixups:
            address = self.labels[label]
            self.code[offset:offset+2] = [address & 255, address >> 8]
        return self.code

def save(name, spans):
    lines = ['# Original MIT Z80 fixture. Generated by philips.py. Offsets are file offsets.']
    for offset, data in spans:
        for i in range(0, len(data), 16):
            lines.append(f'{offset+i:04x}: ' + ' '.join(f'{x:02x}' for x in data[i:i+16]))
    Path(__file__).with_name(name+'.hex').write_text('\n'.join(lines)+'\n')

# System starts with page 0/1 BIOS and page 2/3 RAM. Initialize the expanded
# slot and mapper on MSX2 (ordinary writes/unused ports are harmless on MSX1).
s = Z80(0x100)
s.emit(0xf3, 0x3e, 0xfc, 0x32, 0xff, 0xff, 0x3e, 1, 0xd3, 0xfe,
       0x3e, 2, 0xd3, 0xff, 0x31, 0, 0xf0)
# Probe parked ASCII8SRAM2 cartridge through normal slot mapping.
s.emit(0x3e, 0xd4, 0xd3, 0xa8, 0x3a, 0, 0x40, 0x32, 0x10, 0xc0,
       0x3e, 0x20, 0x32, 0, 0x70, 0x3e, 0x6d, 0x32, 0x23, 0x81,
       0x3e, 0xf0, 0xd3, 0xa8)
# Copy a sub-ROM probe to RAM so page 0 can be switched safely.
s.emit(0x21, 0, 3, 0x11, 0, 0xc1, 0x01, 17, 0, 0xed, 0xb0, 0xcd, 0, 0xc1)
# Discover AB and call its vector with the real CPU, no host BIOS service.
s.emit(0x3e, 0xf8, 0xd3, 0xa8, 0x3a, 0, 0x40, 0xfe, ord('A'))
s.jump(0xc2, 'fail')
s.emit(0x3a, 1, 0x40, 0xfe, ord('B'))
s.jump(0xc2, 'fail')
s.emit(0x2a, 2, 0x40, 0x11, 0x80, 1, 0xd5, 0xe9) # vector returns at 0180
s.label('fail'); s.emit(0x76); s.jump(0xc3, 'fail')
trampoline = [0x3e, 0xf3, 0xd3, 0xa8, 0x3a, 0, 1, 0x32, 0x11, 0xc0,
              0x3e, 0xf0, 0xd3, 0xa8, 0xc9, 0, 0]
save('philips-system', [(0, [0xc3, 0, 1]), (0x100, s.done()),
                         (0x180, [0x76, 0x18, 0xfd]), (0x300, trampoline)])

# Disk ROM init reads sector 1 directly into page-2 RAM and executes it.
r = Z80(0x4100)
r.emit(0x3e, 0x80, 0x32, 0xfd, 0x7f, 0xaf, 0x32, 0xfc, 0x7f,
       0x32, 0xf9, 0x7f, 0x3e, 1, 0x32, 0xfa, 0x7f,
       0x3e, 0x80, 0x32, 0xf8, 0x7f, 0x21, 0, 0x80, 0x01, 0, 2)
r.label('byte'); r.emit(0x11, 0xff, 0xff)
r.label('poll'); r.emit(0x3a, 0xff, 0x7f, 0xcb, 0x7f); r.jump(0xca, 'data')
r.emit(0xcb, 0x77); r.jump(0xca, 'fail')
r.emit(0x1b, 0x7a, 0xb3); r.jump(0xc2, 'poll'); r.jump(0xc3, 'fail')
r.label('data'); r.emit(0x3a, 0xfb, 0x7f, 0x77, 0x23, 0x0b, 0x78, 0xb1); r.jump(0xc2, 'byte')
r.emit(0x3a, 0xf8, 0x7f, 0xe6, 0xfc); r.jump(0xc2, 'fail'); r.emit(0xc3, 0, 0x80)
r.label('fail'); r.emit(0x3e, 0xee, 0x32, 0, 0xc0, 0x76); r.jump(0xc3, 'fail')
save('philips-disk', [(0, [ord('A'), ord('B'), 0, 0x41]), (0x100, r.done())])

# Sector code paints a green backdrop (real VDP output) and writes 512 A6 bytes
# to sector 9 on the side in 81F1, polling active-low IRQ/DRQ. Mode byte 81F0 selects force interrupt
# after the first byte (1) or service timeout (2); default is a complete write.
p = Z80(0x8000)
p.emit(0x3e, 0xa5, 0x32, 0, 0xc0,
       0x3e, 0, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
       0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99,
       0x3e, 0xf2, 0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
       0x3a, 0xf1, 0x81, 0x32, 0xfc, 0x7f,
       0x3e, 9, 0x32, 0xfa, 0x7f, 0x3e, 0xa0, 0x32, 0xf8, 0x7f,
       0x01, 0, 2)
p.label('byte'); p.emit(0x11, 0xff, 0xff)
p.label('poll'); p.emit(0x3a, 0xff, 0x7f, 0xcb, 0x7f); p.jump(0xca, 'data')
p.emit(0xcb, 0x77); p.jump(0xca, 'done')
p.emit(0x1b, 0x7a, 0xb3); p.jump(0xc2, 'poll')
p.emit(0x3e, 0xfe); p.jump(0xc3, 'record')
p.label('data'); p.emit(0x3e, 0xa6, 0x32, 0xfb, 0x7f,
                        0x3a, 0xf0, 0x81, 0xfe, 1); p.jump(0xca, 'abort')
p.emit(0xfe, 2); p.jump(0xca, 'timeout')
p.emit(0x0b, 0x78, 0xb1); p.jump(0xc2, 'byte'); p.jump(0xc3, 'done')
p.label('abort'); p.emit(0x3e, 0xd8, 0x32, 0xf8, 0x7f); p.jump(0xc3, 'done')
p.label('timeout'); p.emit(0x11, 0xff, 0xff)
p.label('delay'); p.emit(0x1b, 0x7a, 0xb3); p.jump(0xc2, 'delay')
p.label('done'); p.emit(0x3a, 0xf8, 0x7f)
p.label('record'); p.emit(0x32, 1, 0xc0, 0x3e, 0x5a, 0x32, 2, 0xc0)
p.label('halt'); p.emit(0x76); p.jump(0xc3, 'halt')
save('philips-sector', [(0, p.done()), (0x1f0, [0, 0])])

# Issue #47 movement probe, executed as a sector through the same AB disk ROM.
# All instructions and trace expectations are original. Seek 0 -> 5 at 6 ms,
# observe Track 2 with BUSY, force interrupt, wait beyond the original seek,
# then read track 2 / sector 1 and write a trace to track 2 / sector 9.
q = Z80(0x8000)
def load(address):
    q.emit(0x3a, address & 255, address >> 8)
def store(address):
    q.emit(0x32, address & 255, address >> 8)
def value(address, byte):
    q.emit(0x3e, byte); store(address)
def check(byte, mask=255):
    if mask != 255:
        q.emit(0xe6, mask)
    q.emit(0xfe, byte); q.jump(0xc2, 'fail')
def record(address, register, expected, mask=255):
    load(register); store(address); check(expected, mask)

value(0x7ffb, 5); value(0x7ff8, 0x10)
q.emit(0x11, 0xff, 0xff)
q.label('moving'); load(0x7ff9); q.emit(0xfe, 2); q.jump(0xca, 'progress')
q.jump(0xd2, 'fail') # A > 2 means intermediate motion was skipped.
q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'moving'); q.jump(0xc3, 'fail')
q.label('progress')
record(0x9000, 0x7ff9, 2)
record(0x9001, 0x7ff8, 1, 0x11) # BUSY, no seek error.
record(0x9002, 0x7fff, 0xff) # Active-low IRQ and DRQ both inactive.
value(0x7ff8, 0xd8)
record(0x9003, 0x7ff9, 2)
record(0x9004, 0x7fff, 0xbf) # Immediate IRQ, no DRQ.
record(0x9005, 0x7ff8, 0, 0x11) # Not BUSY; acknowledge IRQ.
record(0x9006, 0x7fff, 0xff)
q.emit(0x11, 0xff, 0xff)
q.label('delay'); q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'delay')
record(0x9007, 0x7ff9, 2) # Future pulses must remain canceled.
value(0x7ffa, 1); value(0x7ff8, 0x80)
q.emit(0x21, 0x00, 0x92, 0x01, 0, 2)
q.label('read_byte'); q.emit(0x11, 0xff, 0xff)
q.label('read_poll'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xca, 'read_data')
q.emit(0xcb, 0x77); q.jump(0xca, 'fail')
q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'read_poll'); q.jump(0xc3, 'fail')
q.label('read_data'); load(0x7ffb); check(0x62)
q.emit(0x77, 0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'read_byte')
load(0x7ff8); check(0, 0xfd)
# Copy eight observations over the first eight bytes of the read buffer.
q.emit(0x21, 0, 0x90, 0x11, 0, 0x92, 0x01, 8, 0, 0xed, 0xb0)
value(0x7ffa, 9); value(0x7ff8, 0xa0)
q.emit(0x21, 0, 0x92, 0x01, 0, 2)
q.label('write_byte'); q.emit(0x11, 0xff, 0xff)
q.label('write_poll'); load(0x7fff); q.emit(0xcb, 0x7f); q.jump(0xca, 'write_data')
q.emit(0xcb, 0x77); q.jump(0xca, 'fail')
q.emit(0x1b, 0x7a, 0xb3); q.jump(0xc2, 'write_poll'); q.jump(0xc3, 'fail')
q.label('write_data'); q.emit(0x7e); store(0x7ffb)
q.emit(0x23, 0x0b, 0x78, 0xb1); q.jump(0xc2, 'write_byte')
load(0x7ff8); check(0, 0xfd)
q.emit(0x3e, 0xa5); store(0xc020)
q.emit(0x3e, 0xf2); q.jump(0xc3, 'paint') # Green success, red failure.
q.label('fail'); q.emit(0x3e, 0xee); store(0xc020); q.emit(0x3e, 0xf6)
q.label('paint'); q.emit(0xd3, 0x99, 0x3e, 0x87, 0xd3, 0x99,
    0xaf, 0xd3, 0x99, 0x3e, 0x80, 0xd3, 0x99,
    0x3e, 0x40, 0xd3, 0x99, 0x3e, 0x81, 0xd3, 0x99)
q.label('halt'); q.emit(0x76); q.jump(0xc3, 'halt')
movement = q.done()
assert len(movement) <= 510
save('philips-movement', [(0, movement)])
